require_once __DIR__.'/../includes/verificar_sesion.php';$roles_permitidos=['administrador'];require_once __DIR__.'/../includes/verificar_rol.php';require_once __DIR__.'/../config/conexion.php';if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)$_POST['id_pago'];$q=$pdo->prepare('UPDATE pagos SET estado="Pagado",fecha_pago=COALESCE(fecha_pago,NOW()) WHERE id_pago=?');$q->execute([$id]);establecer_mensaje('exito','Pago marcado como pagado.');redirigir('pagos.php');}$q=$pdo->query('SELECT p.*,s.marca,s.modelo,u.nombre AS cliente FROM pagos p JOIN solicitudes s ON s.id_solicitud=p.id_solicitud JOIN usuarios u ON u.id_usuario=s.id_cliente ORDER BY p.id_pago DESC');$pagos=$q->fetchAll();$titulo_pagina='Pagos';$ruta_base='../';require_once __DIR__.'/../includes/encabezado.php';
?><div class="cabecera-panel"><div><span class="etiqueta">COBRANZA</span><h1>Pagos y facturación</h1><p>Registra y consulta los pagos simulados del taller.</p></div><a class="boton boton-secundario" href="facturacion.php">Ver facturación</a></div><section class="tabla-contenedor"><table class="tabla"><thead><tr><th>ID</th><th>Cliente</th><th>Servicio</th><th>Monto</th><th>Método</th><th>Fecha</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($pagos as $p): ?><tr><td>#<?= $p['id_pago'] ?></td><td><?= escapar($p['cliente']) ?></td><td><?= escapar($p['marca'].' '.$p['modelo']) ?></td><td>$<?= number_format($p['monto'],2) ?></td><td><?= escapar($p['metodo_pago']) ?></td><td><?= $p['fecha_pago']?date('d/m/Y H:i',strtotime($p['fecha_pago'])):'—' ?></td><td><span class="<?= estado_clase($p['estado']) ?>"><?= escapar($p['estado']) ?></span></td><td><?php if($p['estado']==='Pendiente'): ?><form method="post"><input type="hidden" name="id_pago" value="<?= $p['id_pago'] ?>"><button class="boton boton-pequeno" type="submit">Marcar pagado</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></section><?php require_once __DIR__.'/../includes/pie.php'; ?>


